referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  const object = (v) => v !== null && typeof v === "object" && !Array.isArray(v);
  const visit = (v) =>
    typeof v === "number"
      ? v + d.delta
      : Array.isArray(v)
        ? v.map(visit)
        : object(v)
          ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, visit(x)]))
          : v;
  return visit(d.value);
}

