type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
export function solve(input: Json): Json {
  const d = input as any;
  const object = (v: any): boolean => v !== null && typeof v === "object" && !Array.isArray(v);
  const visit = (v: any): any =>
    typeof v === "number"
      ? v + d.delta
      : Array.isArray(v)
        ? v.map(visit)
        : object(v)
          ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, visit(x)]))
          : v;
  return visit(d.value);
}
